  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError('Matrix must be a nonempty list of lists')
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('Rows must have consistent length')
    # Compute document frequency per column (count of non-zero entries)
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # Compute IDF
    idf = []
    for d in df:
        idf_val = math.log(1 + n_rows / (1 + d))
        # Round to 6 decimal places
        idf.append(round(idf_val, 6))
    # Build weighted matrix and row degrees
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = []
        row_sum = 0.0
        for j, val in enumerate(row):
            w = val * idf[j]
            weighted_row.append(w)
            row_sum += w
        weighted_matrix.append(weighted_row)
        row_degree.append(round(row_sum, 6))
    return {
        'idf': idf,
        'row_degree': row_degree,
        'weighted_matrix': weighted_matrix
    }"
}
